n//   튀기 = 115% → 96% → 104% → 100% (약 0.6초)\nfunction pop(n) {\n  const ws = [$w('Q_OPT_' + n) || $w('Q_CHIP_' + n), QZ.mode === 'drag' ? $w('Q_BLANK_FILL') : null].filter(Boolean);\n  if (!ws.length) return;\n  const odd = (P.zs = !P.zs);\n  const steps = [[odd ? '115%' : '115.1%', 'ease-out 170ms', 180], [odd ? '96%' : '96.1%', 'ease-in-out 150ms', 160], [odd ? '104%' : '104.1%', 'ease-in-out 130ms', 140], ['100%', 'ease-out 120ms', 0]];\n  let i = 0;\n  (function go() {\n    const st = steps[i++];\n    if (!st) return;\n    for (const w of ws) w.zoomTo(st[0], st[0], { timing: st[1] });\n    if (st[2] && !after(st[2], go)) for (const w of ws) w.zoomTo('100%', '100%');\n  })();\n}\nfunction solved(a) {\n  state(a, 'c');\n  if ($w('Q_SLOT_' + a + '_IMG')) {\n    show('Q_SLOT_' + a + '_IMG', true);\n    show('Q_SLOT_FRAME', true);\n    show('Q_BLANK', false);\n    show('Q_BLANK_Q', false);\n  }\n  show('Q_OPT_' + a + '_REVEAL', true);\n  show('Q_OPT_' + a + '_TICK', true);\n  const gd = $w('Q_OPT_' + a + '_GUIDE');\n  if (gd) gd.set('strokeStyle', '#2FD3C7');\n  const t = $w('Q_OPT_' + a + '_TEXT');\n  const txt = t ? String(t.get('text') || '') : '';\n  if (QZ.mode === 'drag') {\n    const fill = $w('Q_BLANK_FILL');\n    if (fill) {\n      fill.set('text', txt);\n      show('Q_BLANK_FILL', true);\n      show('Q_BLANK_FILL_IMG', true);\n      show('Q_OPT_' + a, false);\n      ghost(a, true);\n    } else {\n      const w = $w('Q_OPT_' + a);\n      const b = QZ.blank;\n      const cb = cardBox(a);\n      if (w && b && cb) w.moveTo(b[0] + (b[2] - cb[2]) / 2, b[1] + (b[3] - cb[3]) / 2, { timing: 'ease-out 200ms' });\n      const ok = $w('Q_OPT_' + a + '_OKTEXT');\n      const lab = $w('Q_BLANK_LABEL');\n      if (ok) ok.set('text', (lab ? String(lab.get('text') || '') + ' · ' : '') + txt);\n      show('Q_OPT_' + a + '_OKTEXT', true);\n      for (const x of ['_NUM', '_TEXT']) show('Q_OPT_' + a + x, false);\n      show('Q_SPK_OPT_' + a, false);\n      ghost(a, true);\n    }\n    show('Q_BLANK', false);\n    show('Q_BLANK_Q', false);\n    show('Q_BLANK_LABEL', false);\n  }\n  // 빈 말풍선(EN-03 시안): 회색 점선 → 청록, \"이름:  고른 글\" + 소리 단추\n  if (QZ.fill) {\n    const dn = $w('Q_FILL_DONE');\n    const nm = $w('Q_FILL_NAME');\n    if (dn) dn.set('text', (nm ? String(nm.get('text') || '') + '  ' : '') + txt);\n    show('Q_FILL_DONE', true);\n    show('Q_FILL', false);\n    show('Q_FILL_NAME', false);\n    fillBox(true);\n    show('Q_SPK_FILL', true);\n    P.fillA = a;\n  }\n}\nfunction fillBox(on) {\n  for (const b of ['Q_FILL_BOX', 'Q_FILL_TAIL']) {\n    const w = $w(b);\n    if (!w) continue;\n    w.set('fillStyle', on ? '#E6FAF8' : '#EEF1F6');\n    w.set('strokeStyle', on ? '#2FD3C7' : '#9DB7E8');\n    w.set('lineDash', on ? 'solid' : 'dashed');\n  }\n}\n// 터치형 카드도 끌기를 켜 둔다 — 움직이지 않게 붙잡고(아래 이벤트), 이벤트만 받는다: 실행기는 누른 채 움직였다 떼면 Tap 도 누르기 끝도\n// 보내지 않지만, 끌 수 있는 위젯은 어디서 떼든 Drag End 를 보낸다 → 판정이 없었으면 노란 표시를 푼다 (사용자 지시 2026-10-19 \"누르고 움직인 경우 계속 누른 상태\")\n/** 마지막 손 떼기 자리(화면 좌표 1920×1080) — 브라우저 pointerup·touchend 를 적어 둔다(위젯은 건드리지 않음). 0.6초 넘게 지난 것은 버린다 */\nfunction upPoint() {\n  const u = window.__kqUp;\n  if (!u || Date.now() - u.t > 600) return null;\n  const st = document.getElementById('apn$CExe_1_cntr');\n  const r = st && st.getBoundingClientRect();\n  if (!r || !r.width || !r.height) return null;\n  return [((u.x - r.left) / r.width) * 1920, ((u.y - r.top) / r.height) * 1080];\n}\nfunction holdTouch() {\n  if (QZ.mode !== 'touch') return;\n  if (!window.__kqUpOn) {\n    window.__kqUpOn = true;\n    const note = function (x, y) {\n      window.__kqUp = { x: x, y: y, t: Date.now() };\n    };\n    window.addEventListener('pointerup', function (ev) { note(ev.clientX, ev.clientY); }, true);\n    window.addEventListener('mouseup', function (ev) { note(ev.clientX, ev.clientY); }, true);\n    window.addEventListener('touchend', function (ev) {\n      const t = ev.changedTouches && ev.changedTouches[0];\n      if (t) note(t.clientX, t.clientY);\n    }, true);\n  }\n  for (let i = 1; i <= cnt(); i++) {\n    const w = $w('Q_OPT_' + i);\n    if (!w) continue;\n    w.set('dragX', true);\n    w.set('dragY', true);\n  }\n}\nfunction setDrag(on) {\n  if (QZ.mode !== 'drag') return;\n  for (let i = 1; i <= cnt(); i++) {\n    const w = $w('Q_OPT_' + i);\n    if (!w) continue;\n    const v = on && !P.dead[i];\n    w.set('dragX', v);\n    w.set('dragY', v);\n  }\n}\nconst ACT = {\n  wait: function () {\n    return wait(1000) ? 'wait' : '';\n  },\n  next: function () {\n    ASPEN_MODULE.nav.next();\n  },\n  hint: function () {\n    // 힌트 프리팹(HINT_*)이 창을 열고 힌트 낭독 — 끝나거나 닫으면 'hint.closed' 를 받아 차례를 이어 간다(아래 이벤트)\n    if (!$w('HINT')) return '';\n    recordHint('popup', P.hintVia || 'auto');\n    P.hintVia = '';\n    P.waitHint = true;\n    fireEvent('Custom Event', fbHint());\n    return 'wait';\n  },\n  // 끌기 시범 — 빈 카드(정답 아님)를 손가락이 위로 조금 끌었다 사라짐. 실제 카드·배치·시도 횟수는 그대로, 페이지에 들어올 때마다 한 번\n  demo: function () {\n    if (P.demoed) return '';\n    P.demoed = true;\n    const c = $w('Q_DEMO_CARD');\n    const h = $w('Q_HAND');\n    if (!c || !h) return '';\n    const x = QZ.dragDemo[0];\n    const y = QZ.dragDemo[1];\n    c.set('x', x);\n    c.set('y', y);\n    h.set('x', x + 160);\n    h.set('y', y + 50);\n    show('Q_DEMO_CARD', true);\n    show('Q_HAND', true);\n    // 보기 카드(레이어 컨테이너) 위로 — 위젯 순서만으로는 카드 뒤에 그려졌다(사용자 지적 2026-10-27)\n    c.zIndexTo('top');\n    h.zIndexTo('top');\n    after(300, function () {\n      c.moveTo(x, y - 150, { timing: 'ease-in-out 900ms' });\n      h.moveTo(x + 160, y - 100, { timing: 'ease-in-out 900ms' });\n      after(1400, function () {\n        show('Q_DEMO_CARD', false);\n        show('Q_HAND', false);\n      });\n    });\n    return '';\n  },\n  reveal: function () {\n    if (QZ.slots) return revealSlots();\n    const a = answer();\n    if (QZ.mode === 'drag') for (let i = 1; i <= cnt(); i++) if (i !== a) home(i, true);\n    recordHint('answer', 'auto');\n    solved(a);\n    pop(a);\n    done();\n  },\n};\nfunction judge(n) {\n  P.busy = false;\n  if (n === answer()) {\n    P.lock = true;\n    setDrag(false);\n    solved(n);\n    // 정답 연출은 카드 청록·효과음·칭찬 낭독(오버레이 별 피드백 feedback.show 는 쓰지 않음 — 사용자 결정 2026-10-14)\n    record(true, n);\n    done();\n    // 정답 뒤 소리(Q_V_ANS — 파일이 있을 때만). 다음 페이지는 학습자가 다음 단추로 — 저절로 넘기는 것은 QZ.next: true·화면 설정 \"저절로\"일 때만(사용자 지시 2026-10-19·2026-10-21)\n    seq(fbOk(['Q_SFX_OK', pick(['Q_V_OK_1', 'Q_V_OK_2', 'Q_V_OK_3', 'Q_V_OK_4', 'Q_V_OK_5'])], 'Q_SFX_OK').concat(hasMedia('Q_V_ANS') ? ['Q_V_ANS'] : [], autoNext() ? ['@wait', '@next'] : []), true);\n    return;\n  }\n  P.wrong = (P.wrong || 0) + 1;\n  record(false, n);\n  // 오답 카드는 회색·내용 45%(시안 오답) — 오답 차례(낭독·힌트)가 끝나면 보통으로 되돌린다(step 의 P.revive). 그동안은 다시 못 고름. 끌기는 제자리로 돌아간 뒤\n  P.dead[n] = true;\n  P.revive = n;\n  state(n, 'w');\n  if (QZ.mode === 'drag') {\n    home(n, true);\n    setDrag(false); // 오답 낭독·힌트가 끝나면 step 이 다시 켬\n  } else shake(n);\n  const NG = fbNg(QZ.ng || [['Q_SFX_NG', 'Q_V_RETRY'], ['Q_SFX_NG', '@hint'], ['Q_SFX_NG', 'Q_V_ANSWER', '@reveal', '@wait', '@next']], 'Q_SFX_NG');\n  const auto = autoNext();\n  const list = NG[Math.min(P.wrong, NG.length) - 1].filter(function (x) {\n    return auto || (x !== '@wait' && x !== '@next');\n  });\n  // 정답 공개 뒤에도 정답 뒤 소리(파일이 있을 때만)\n  const rv = list.indexOf('@reveal');\n  if (rv >= 0 && hasMedia('Q_V_ANS')) list.splice(rv + 1, 0, 'Q_V_ANS');\n  // 정답 공개면 더 고를 수 없다\n  if (list.indexOf('@reveal') >= 0) {\n    P.lock = true;\n    setDrag(false);\n  }\n  seq(list, true);\n}\n// 터치 누르는 동안: 노란 선택 + 105% (사용자 지시 2026-10-19 \"누를 때 노란색, 뗐을 때 정오답 체크\") — 떼면(Tap) choose 가 판정\n//   실행기에 누르기 끝 이벤트가 없어(타이머 안에서는 위젯도 못 다룸), 카드 밖에서 떼면 다음에 다른 곳을 누를 때 표시를 푼다(press(0)) — 오래 눌러도 노란 채로\nfunction press(n) {\n  const was = P.press;\n  if (was && was !== n && !P.busy) {\n    state(was, P.dead[was] ? 'w' : 'd');\n    const pw = $w('Q_OPT_' + was) || $w('Q_CHIP_' + was);\n    if (pw) pw.zoomTo('100%', '100%', { timing: 'ease-out 120ms' });\n  }\n  P.press = n;\n  if (!n) return;\n  state(n, 's');\n  const w = $w('Q_OPT_' + n) || $w('Q_CHIP_' + n);\n  const z = (P.zs = !P.zs) ? '105%' : '105.1%';\n  if (w) w.zoomTo(z, z, { timing: 'ease-out 120ms' });\n}\n// 터치 뗌 = 고름 → 연출: 노란 선택 + 110% 로 커졌다 돌아옴 → 판정(정답 청록 / 오답 회색·흔들림 + 피드백 낭독).\n//   연출(P.busy)과 피드백 낭독(P.fb)이 끝날 때까지 이 페이지의 다른 누르기는 받지 않는다 (사용자 지시 2026-10-19 \"연출이 시작되면 다른 클릭을 막고, 표현까지 하고 난 뒤 다른 걸 클릭\")\nfunction choose(n) {\n  const w = $w('Q_OPT_' + n) || $w('Q_CHIP_' + n);\n  P.press = 0;\n  P.busy = true;\n  state(n, 's');\n  if (!w) return judge(n);\n  // 정답·오답 모두 노란색 → 110% → 원래 크기 → 판정 색 (사용자 지시 2026-10-19 \"정답을 선택할 때는 노란색 → 스케일 애니 → (원래 크기로 돌아오고) 파란색\")\n  const big = (P.zs = !P.zs) ? '110%' : '110.1%';\n  w.zoomTo(big, big, { timing: 'ease-out 140ms' });\n  if (!after(150, function () {\n    w.zoomTo('100%', '100%', { timing: 'ease-in 150ms' });\n    if (!after(160, function () { judge(n); })) judge(n);\n  })) judge(n);\n}\n// 끌기: 놓은 카드 가운데가 빈칸 안이면 판정, 밖이면 제자리(시도 안 셈)\nfunction dropped(n) {\n  if (QZ.slots) return droppedSlot(n);\n  const w = $w('Q_OPT_' + n);\n  const c = cardBox(n);\n  const b = QZ.blank;\n  if (!w || !c || !b) return;\n  w.zoomTo('100%', '100%', { timing: 'ease-out 120ms' });\n  const cx = Number(w.get('x')) + c[2] / 2;\n  const cy = Number(w.get('y')) + c[3] / 2;\n  if (cx >= b[0] && cx <= b[0] + b[2] && cy >= b[1] && cy <= b[1] + b[3]) judge(n);\n  else {\n    state(n, 'd');\n    home(n, true);\n  }\n}\n\n// ── 빈칸 여러 개(순서 있음 — QZ.slots, TPL-QCM-24 「들은 순서대로 장바구니에」, 사용자 결정 2026-10-21) ──\n//   한 칸에 1장(이미 있던 카드는 제자리로) · 칸에 든 카드를 다시 끌면 칸이 빔 · 모든 칸이 차면 한꺼번에 판정 ·\n//   오답이면 틀린 칸의 카드만 회색 → 제자리(맞는 칸 카드는 그대로) · 정답 공개 = 정답 카드를 칸에 넣어 보여 줌. QZ.slots 가 없으면 빈칸 하나(위 dropped)\n/** 칸마다 정답 보기 번호 — 글 Q_ANSWER 「1,3」(KICE 속성 \"정답\"), 틀린 값이면 QZ.answers */\nfunction answers() {\n  const w = $w('Q_ANSWER');\n  const v = w ? String(w.get('text') || '').split(',').map(function (x) { return parseInt(x, 10); }) : [];\n  return QZ.slots.map(function (_, i) { return v[i] > 0 && v[i] <= cnt() ? v[i] : QZ.answers[i]; });\n}\n/** 카드 가운데가 든 칸 번호(1부터, 없으면 0) */\nfunction slotAt(n) {\n  const w = $w('Q_OPT_' + n);\n  const c = cardBox(n);\n  if (!w || !c) return 0;\n  const cx = Number(w.get('x')) + c[2] / 2;\n  const cy = Number(w.get('y')) + c[3] / 2;\n  for (let i = 0; i < QZ.slots.length; i++) {\n    const b = QZ.slots[i];\n    if (cx >= b[0] && cx <= b[0] + b[2] && cy >= b[1] && cy <= b[1] + b[3]) return i + 1;\n  }\n  return 0;\n}\n/** 카드 n 을 칸 s 에 맞춰 넣음(카드 가운데 = 칸 가운데) — 원래 자리 점선은 남김 */\nfunction putIn(n, s, anim) {\n  const w = $w('Q_OPT_' + n);\n  const c = cardBox(n);\n  const b = QZ.slots[s - 1];\n  P.in[s] = n;\n  P.at[n] = s;\n  ghost(n, true);\n  if (!w || !c || !b) return;\n  // 카드가 든 칸의 점선 상자는 숨김(카드와 칸 모서리 둥글기가 달라 점선이 비쳐 보임 — 시안 정답 화면엔 없음, TPL-QCM-26 2026-10-27 사용자 지적)\n  show('Q_BLANK_' + s, false);\n  if (QZ.slotFit) return fit(n, b);\n  const x = Math.round(b[0] + (b[2] - c[2]) / 2);\n  const y = Math.round(b[1] + (b[3] - c[3]) / 2);\n  if (anim) w.moveTo(x, y, { timing: 'ease-out 150ms' });\n  else {\n    w.set('x', x);\n    w.set('y', y);\n  }\n}\n/**\n * QZ.slotFit — 카드를 칸 상자 b 크기로(칸에 넣을 때) 또는 원래 크기로(b 없음 — 지금 가운데 그대로, 칸에서 뺄 때).\n * 바탕·글(_BG·_TEXT)은 늘어난 만큼 크기를, 그 밖의 안 위젯(그림 등)은 반만큼 옮겨 가운데를 지킨다. 실행기 set('x') 는 화면 좌표(컨테이너를 옮기면 안 위젯도 따라감).\n */\nconst FIT_GROW = ['_BG', '_TEXT'];\nconst FIT_KIDS = ['_BG', '_TEXT', '_IMG', '_NAME'];\nfunction fit(n, b) {\n  const w = $w('Q_OPT_' + n);\n  const c = cardBox(n);\n  if (!w || !c) return;\n  P.fit = P.fit || {};\n  if (!b && !P.fit[n]) return;\n  const x0 = Number(w.get('x'));\n  const y0 = Number(w.get('y'));\n  // 안 위젯 원래 모양(카드 왼쪽 위 기준) — 처음 맞출 때(원래 크기일 때) 기억\n  if (!P.fit[n]) {\n    P.fit[n] = { on: false, kids: {} };\n    for (const k of FIT_KIDS) {\n      const q = $w('Q_OPT_' + n + k);\n      if (q) P.fit[n].kids[k] = [Number(q.get('x')) - x0, Number(q.get('y')) - y0, Number(q.get('w')), Number(q.get('h'))];\n    }\n  }\n  const cw = Number(w.get('w'));\n  const ch = Number(w.get('h'));\n  const nb = b || [Math.round(x0 + cw / 2 - c[2] / 2), Math.round(y0 + ch / 2 - c[3] / 2), c[2], c[3]];\n  const dw = nb[2] - c[2];\n  const dh = nb[3] - c[3];\n  // 그림은 칸 높이 비율만큼 키움(시안 칸 안 그림 147×120 → 167×137)\n  const sc = nb[3] / c[3];\n  w.set('x', nb[0]);\n  w.set('y', nb[1]);\n  w.set('w', nb[2]);\n  w.set('h', nb[3]);\n  layerFit(w);\n  for (const k in P.fit[n].kids) {\n    const q = $w('Q_OPT_' + n + k);\n    const o = P.fit[n].kids[k];\n    if (!q) continue;\n    if (FIT_GROW.indexOf(k) >= 0) {\n      q.set('x', Math.round(nb[0] + o[0]));\n      q.set('y', Math.round(nb[1] + o[1]));\n      q.set('w', o[2] + dw);\n      q.set('h', o[3] + dh);\n      continue;\n    }\n    // 가운데를 지키며(카드 크기 차이의 반만큼) 그림은 sc 배\n    const s2 = k === '_IMG' ? sc : 1;\n    const mx = nb[0] + o[0] + o[2] / 2 + dw / 2;\n    const my = nb[1] + o[1] + o[3] / 2 + dh / 2;\n    q.set('w', Math.round(o[2] * s2));\n    q.set('h', Math.round(o[3] * s2));\n    q.set('x', Math.round(mx - (o[2] * s2) / 2));\n    q.set('y', Math.round(my - (o[3] * s2) / 2));\n  }\n  P.fit[n].on = !!b;\n}\n/** 레이어 컨테이너 크기를 바꾸면 실행기는 컨테이너 div 만 바꾸고 안쪽 레이어 div(넘치면 자름)는 처음 크기 그대로라 키운 만큼 잘린다 — 안쪽 레이어 div 크기를 컨테이너에 맞춤 */\nfunction layerFit(w) {\n  try {\n    const all = document.getElementsByTagName('div');\n    for (let i = 0; i < all.length; i++)\n      if (all[i].apnOID === w.id) {\n        const el = all[i];\n        for (let j = 0; j < el.children.length; j++) {\n          const k = el.children[j];\n          if (k.getAttribute('title')) continue;\n          k.style.width = el.style.width;\n          k.style.height = el.style.height;\n        }\n      }\n  } catch (x) {}\n}\n/** 카드를 칸에서 빼고 제자리로 */\nfunction outOf(n, anim) {\n  const s = P.at[n];\n  if (s && P.in[s] === n) P.in[s] = 0;\n  if (s) show('Q_BLANK_' + s, true);\n  P.at[n] = 0;\n  if (QZ.slotFit && P.fit && P.fit[n] && P.fit[n].on) fit(n, null);\n  home(n, anim);\n}\nfunction droppedSlot(n) {\n  const w = $w('Q_OPT_' + n);\n  if (!w) return;\n  w.zoomTo('100%', '100%', { timing: 'ease-out 120ms' });\n  state(n, 'd');\n  const s = slotAt(n);\n  if (!s) return outOf(n, true);\n  const m = P.in[s];\n  // 맞아서 남겨 둔 칸(칸 연출)에는 못 넣음 — 제자리로\n  if (m && m !== n && P.dead[m]) return outOf(n, true);\n  if (m && m !== n) {\n    state(m, 'd');\n    outOf(m, true);\n  }\n  putIn(n, s, true);\n  if (QZ.slotNow) return judgeOne(n, s);\n  for (let i = 1; i <= QZ.slots.length; i++) if (!P.in[i]) return;\n  // 다 찼다 — 들어가는 움직임 뒤 판정, 그동안 끌기·누르기 막음\n  P.busy = true;\n  setDrag(false);\n  if (!after(250, judgeSlots)) judgeSlots();\n}\nfunction recordSlots(ok, a) {\n  const ms = Date.now() - (P.t0 || Date.now());\n  if (DBG) console.log('[quiz] 답안(칸)', QZ.code, JSON.stringify(P.in), ok, ms);\n  ASPEN_MODULE.rec.answer({\n    qid: QZ.code,\n    type: 'dnd',\n    value: QZ.slots.map(function (_, i) { return ASPEN_MODULE.pair('slot' + (i + 1), P.in[i + 1] || 0); }),\n    answer: a.map(function (x, i) { return ASPEN_MODULE.pair('slot' + (i + 1), x); }),\n    correct: ok,\n    ms: ms,\n  });\n  judged();\n}\nfunction judgeSlots() {\n  P.busy = false;\n  const a = answers();\n  const wrong = [];\n  // QZ.anyOrder = 칸 순서 상관없음(정답 카드가 아무 칸에나 — TPL-QCM-26), 아니면 칸마다 정한 카드\n  for (let i = 1; i <= QZ.slots.length; i++) if (QZ.anyOrder ? a.indexOf(P.in[i]) < 0 : P.in[i] !== a[i - 1]) wrong.push(i);\n  recordSlots(!wrong.length, a);\n  if (!wrong.length) {\n    P.lock = true;\n    setDrag(false);\n    for (let i = 1; i <= QZ.slots.length; i++) state(P.in[i], 'c');\n    done();\n    seq(fbOk(['Q_SFX_OK', pick(['Q_V_OK_1', 'Q_V_OK_2', 'Q_V_OK_3', 'Q_V_OK_4', 'Q_V_OK_5'])], 'Q_SFX_OK').concat(hasMedia('Q_V_ANS') ? ['Q_V_ANS'] : [], autoNext() ? ['@wait', '@next'] : []), true);\n    return;\n  }\n  P.wrong = (P.wrong || 0) + 1;\n  // 틀린 칸의 카드만 — 회색으로 잠깐 보인 뒤 제자리로, 오답 차례가 끝나면 보통으로(step 의 P.revive)\n  const back = wrong.map(function (i) { return P.in[i]; });\n  back.forEach(function (n) {\n    P.dead[n] = true;\n    state(n, 'w', QZ.slotFit);\n  });\n  // 칸 연출: 맞은 칸 카드는 청록으로 그 칸에 남기고 더 끌지 않음\n  if (QZ.slotFit)\n    for (let i = 1; i <= QZ.slots.length; i++)\n      if (wrong.indexOf(i) < 0 && P.in[i]) {\n        P.dead[P.in[i]] = true;\n        state(P.in[i], 'c');\n      }\n  P.revive = back;\n  setDrag(false);\n  // 정답 공개(3회)로 잠기는 때에도 먼저 돌려보낸다 — 공개는 안내 낭독 뒤(@reveal)\n  if (!after(450, function () { back.forEach(function (n) { if (P.at[n]) outOf(n, true); }); })) back.forEach(function (n) { outOf(n, false); });\n  const NG = fbNg(QZ.ng || [['Q_SFX_NG', 'Q_V_RETRY'], ['Q_SFX_NG', '@hint'], ['Q_SFX_NG', 'Q_V_ANSWER', '@reveal', '@wait', '@next']], 'Q_SFX_NG');\n  const auto = autoNext();\n  const list = NG[Math.min(P.wrong, NG.length) - 1].filter(function (x) {\n    return auto || (x !== '@wait' && x !== '@next');\n  });\n  const rv = list.indexOf('@reveal');\n  if (rv >= 0 && hasMedia('Q_V_ANS')) list.splice(rv + 1, 0, 'Q_V_ANS');\n  if (rv >= 0) P.lock = true;\n  seq(list, true);\n}\n/**\n * QZ.slotNow — 칸 s 에 놓은 카드 n 만 바로 판정. 맞으면 그 칸에 고정(더 못 끎) + 정답 효과음, 모든 칸이 맞으면 정답(칭찬·완료, 남은 카드는 흐리게·완성 틀 Q_DONE_FRAME).\n * 틀리면 회색 → 제자리 + 오답 차례(QZ.ng — 1회 다시·2회 힌트·3회 정답 공개). 시도는 놓을 때마다 한 번(기획서 「오배치 1번 = 1회」)\n */\nfunction judgeOne(n, s) {\n  const a = answers();\n  const ok = QZ.anyOrder ? a.indexOf(n) >= 0 : a[s - 1] === n;\n  if (ok) {\n    P.dead[n] = true;\n    state(n, 'c');\n    for (let i = 1; i <= QZ.slots.length; i++)\n      if (!P.in[i] || !P.dead[P.in[i]]) {\n        seq(['Q_SFX_OK']);\n        return;\n      }\n    recordSlots(true, a);\n    P.lock = true;\n    setDrag(false);\n    for (let i = 1; i <= cnt(); i++) if (a.indexOf(i) < 0) state(i, 'w');\n    show('Q_DONE_FRAME', true);\n    done();\n    seq(fbOk(['Q_SFX_OK', pick(['Q_V_OK_1', 'Q_V_OK_2', 'Q_V_OK_3', 'Q_V_OK_4', 'Q_V_OK_5'])], 'Q_SFX_OK').concat(hasMedia('Q_V_ANS') ? ['Q_V_ANS'] : [], autoNext() ? ['@wait', '@next'] : []), true);\n    return;\n  }\n  recordSlots(false, a);\n  P.wrong = (P.wrong || 0) + 1;\n  P.dead[n] = true;\n  state(n, '